code.store_lock_and_revision:
pub fn lock_scenes(&self, project: &str) -> Result<SceneLock, EditorError> {
    self.require_project(project)?;
    let path = self.project_directory(project).join(".scenes.lock");
    gx_fs::FileLock::exclusive(&path)
        .map(|held| SceneLock { _held: held })
        .map_err(|source| EditorError::Io { path, source })
}

pub fn stored_revision(
    &self,
    project: &str,
    scene_id: &str,
) -> Result<Option<Revision>, EditorError> {
    self.require_project(project)?;
    require_component(scene_id, |id| Refusal::SceneIdInvalid { id })?;
    let path = self.scene_path(project, scene_id);
    let bytes = std::fs::read(&path).map_err(|source| EditorError::Io { path, source })?;
    let Ok(value) = serde_json::from_slice::<serde_json::Value>(&bytes) else {
        return Ok(None);
    };
    Ok(Some(Revision(
        value
            .get("revision")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(0),
    )))
}

code.mcp_command_tool:
    fn handle(&self, mut args: serde_json::Value) -> Result<serde_json::Value, Refusal> {
        let key = take_idempotency_key(&mut args)?;
        let command: EditorCommand = parse_strict::<P>(args.clone())?.into();
        require_revision(&command)?;
        let name = command.name();
        let projects = self.projects.clone();
        let run = move || {
            Workspace::new(Some(projects))
                .execute(command)
                .map_err(|error| match error {
                    CommandError::Refused(refusal) => refusal,
                    CommandError::Store(error) => Refusal::from(error),
                })
                .and_then(to_value)
        };
        match key {
            None => run(),
            Some(key) => LedgerFile::new(self.projects.root().join(IDEMPOTENCY_LEDGER))
                .once(key, &fingerprint(name, &args), run)
                .map(|answer| answer.result),
        }
    }
}

const IDEMPOTENCY_LEDGER: &str = ".idempotency.json";

const IDEMPOTENCY_KEY_MAX: usize = 128;

fn take_idempotency_key(args: &mut serde_json::Value) -> Result<Option<IdempotencyKey>, Refusal> {
    let Some(object) = args.as_object_mut() else {
        return Ok(None);
    };
    let Some(key) = object.remove("idempotencyKey") else {
        return Ok(None);
    };
    match key {
        serde_json::Value::String(key)
            if !key.is_empty()
                && key.chars().count() <= IDEMPOTENCY_KEY_MAX
                && !key.chars().any(char::is_control) =>
        {
            Ok(Some(IdempotencyKey(key)))
        }
        other => Err(Refusal::SceneParseFailed {
            detail: format!(
                "arguments do not match the tool's input schema: idempotencyKey must be a \
                 string of 1 to {IDEMPOTENCY_KEY_MAX} characters with no control characters, got {other}"
            ),
        }),
    }
}

fn require_revision(command: &EditorCommand) -> Result<(), Refusal> {
    let tool = match command {
        EditorCommand::EditScene(EditScene {
            target: SceneTarget::Stored { .. },
            if_revision: None,
            ..
        }) => "scenes.edit",
        EditorCommand::DeleteScene(DeleteScene {
            if_revision: None, ..
        }) => "scenes.delete",
        _ => return Ok(()),
    };
    Err(Refusal::RevisionRequired {
        tool: tool.to_owned(),
    })
}

code.ledger_once:
    pub fn once<T>(
        &mut self,
        key: IdempotencyKey,
        request: &str,
        operation: impl FnOnce() -> Result<T, Refusal>,
    ) -> Result<Once, Refusal>
    where
        T: Serialize,
    {
        if let Some(entry) = self.entries.iter().find(|entry| entry.key == key) {
            if entry.request != request {
                return Err(Refusal::IdempotencyKeyReused { key: key.0 });
            }
            return Ok(Once {
                result: entry.result.clone(),
                replayed: true,
            });
        }
        let result = operation()?;
        let value = serde_json::to_value(result).map_err(|error| Refusal::TransportFailed {
            detail: format!("a write's result could not be recorded: {error}"),
        })?;
        self.record(key, request.to_owned(), value.clone());
        Ok(Once {
            result: value,
            replayed: false,
        })
    }
}

code.ledger_file_once:
    pub fn once<T: Serialize>(
        &self,
        key: IdempotencyKey,
        request: &str,
        operation: impl FnOnce() -> Result<T, Refusal>,
    ) -> Result<Once, Refusal> {
        let failed = |what: &str, error: &dyn std::fmt::Display| Refusal::TransportFailed {
            detail: format!("the idempotency ledger {what}: {error}"),
        };
        let mut lock_path = self.path.clone().into_os_string();
        lock_path.push(".lock");
        let _held = gx_fs::FileLock::exclusive(std::path::Path::new(&lock_path))
            .map_err(|error| failed("could not be locked", &error))?;
        let mut ledger = match std::fs::read(&self.path) {
            Ok(bytes) => serde_json::from_slice::<IdempotencyLedger>(&bytes).map_err(|error| {
                failed("could not be read; delete it to start a new one", &error)
            })?,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                IdempotencyLedger::with_capacity(self.capacity)
            }
            Err(error) => return Err(failed("could not be read", &error)),
        };
        ledger.capacity = self.capacity;
        let answer = ledger.once(key, request, operation)?;
        if !answer.replayed {
            let bytes = serde_json::to_vec(&ledger)
                .map_err(|error| failed("could not be written", &error))?;
            gx_fs::write_atomic(&self.path, &bytes)
                .map_err(|error| failed("could not be written", &error))?;
        }
        Ok(answer)
    }
}
